from pathlib import Path
import json
R=Path(__file__).parent
TASKS=[]
def add(id,cat,ports,body,mutations,stim,checks,extra=''):
 p=R/'tasks'/id
 src=f'module {id}({ports});\n{body}\nendmodule\n'
 files=[f'rtl/{id}.sv']
 if extra: files+=['rtl/helper.sv']
 for variant,code in [('reference',src),('starter',src.replace(*mutations[0][1]))]+[(f'mutants/{n}',src.replace(*change)) for n,change in mutations]:
  d=p/variant/'rtl';d.mkdir(parents=True,exist_ok=True);(d/f'{id}.sv').write_text(code)
  if extra:(d/'helper.sv').write_text(extra)
 cs=[]
 for cid,description,scenario in checks:
  d=p/'checks';d.mkdir(parents=True,exist_ok=True)
  tb='`timescale 1ns/1ps\nmodule tb;\n'+stim+'\ninteger seed; integer ignored; initial begin seed=1; ignored=$value$plusargs("SEED=%d",seed);\n'+scenario+'\n$display("HWBENCH_PASS"); $finish; end\ninitial begin #100000; $fatal(1,"timeout"); end\nendmodule\n'
  (d/f'{cid}.sv').write_text(tb);cs.append(dict(id=cid,tb=f'checks/{cid}.sv',top='tb',description=description))
 (p/'prompt.md').write_text(f'# {id}\n\nImplement/repair the synthesizable SystemVerilog module below. Only modify the listed RTL files. Preserve ports and functional behavior described here.\n\n```systemverilog\nmodule {id}({ports});\n```\n\n'+DESCS[id]+'\n\nNo testbench or simulation system tasks belong in the submitted RTL.\n')
 TASKS.append(dict(id=id,category=cat,title=id.replace('_',' '),path=f'tasks/{id}',files=files,checks=cs,mutants=[dict(id=n,path=f'mutants/{n}',expected_fail_checks=[checks[0][0]]) for n,_ in mutations],tags=['locally_authored','starter_scale']))
DESCS={
'saturating_add':'Unsigned 8-bit combinational addition. y=min(a+b,255); overflow is one iff a+b>255. No clock/reset. Width fixed at 8.',
'priority_encoder':'Combinational 8-bit request. valid=|req. index is the lowest numbered set bit, and zero if req=0. Width fixed at 8.',
'counter':'8-bit counter. On rising clk, synchronous active-high rst clears count. Otherwise en increments modulo 256. Hold when en=0. Reset has priority.',
'fifo':'Two-entry 8-bit synchronous FIFO. Synchronous active-high rst empties FIFO. out_valid=(occupancy>0); in_ready=(occupancy<2), including when full and pop asserted. Transfers occur only valid&&ready. out_data is oldest entry when valid; undefined otherwise. Simultaneous push/pop preserve order and occupancy. No fall-through.',
'stream_pipeline':'One-entry elastic 8-bit stream register. Synchronous active-high rst clears out_valid. in_ready=!out_valid||out_ready. Data transfers on valid&&ready. Hold output data and valid while stalled. Throughput one item per clock after initial latency. Wrapper delegates to helper module elastic_stage; both files may be edited.',
'round_robin':'Two-client round-robin combinational grant with clocked preference. grant=0 if no requests. Single request always granted. Both requests choose preference. Synchronous active-high rst sets preference client 0. On rising clk with accept and a nonzero grant, preference switches to the other client; otherwise hold. Helper choose_grant computes grant. Both files may be edited.'}
add('saturating_add','generation','input [7:0] a,b, output [7:0] y, output overflow','wire [8:0] s={1\'b0,a}+{1\'b0,b}; assign overflow=s[8]; assign y=s[8]?8\'hff:s[7:0];',[('wrap',("s[8]?8'hff:s[7:0]","s[7:0]")),('bad_flag',('assign overflow=s[8]','assign overflow=0'))], 'reg [7:0] a,b; wire [7:0] y; wire overflow; integer i,j,s; saturating_add dut(a,b,y,overflow); task check; begin #1; s=a+b; if(y!==(s>255?255:s)||overflow!==(s>255)) $fatal(1,"sum mismatch a=%d b=%d",a,b); end endtask', [('boundary','Overflow boundary','a=255;b=1;check;a=0;b=0;check;a=127;b=128;check;'),('exhaustive','All 65536 pairs','for(i=0;i<256;i=i+1) for(j=0;j<256;j=j+1) begin a=i;b=j;check;end'),('seeded','Seeded pairs','for(i=0;i<1000;i=i+1) begin a=$random(seed);b=$random(seed);check;end')])
add('priority_encoder','generation','input [7:0] req, output reg [2:0] index, output valid',"integer k; assign valid=|req; always @* begin index=0; for(k=7;k>=0;k=k-1) if(req[k]) index=k; end",[('highest',('k=7;k>=0;k=k-1','k=0;k<8;k=k+1')),('invalid',('assign valid=|req','assign valid=0'))],'reg [7:0] req;wire [2:0] index;wire valid;integer i,k,expect_idx;priority_encoder dut(req,index,valid);task check;begin #1;expect_idx=0;for(k=7;k>=0;k=k-1)if(req[k])expect_idx=k;if(index!==expect_idx[2:0]||valid!== (req!=0))$fatal(1,"priority mismatch req=%h",req);end endtask',[('boundary','Competing requests','req=129;check;req=0;check;req=128;check;'),('exhaustive','All request masks','for(i=0;i<256;i=i+1)begin req=i;check;end'),('seeded','Seeded masks','for(i=0;i<1000;i=i+1)begin req=$random(seed);check;end')])
add('counter','repair','input clk,rst,en, output reg [7:0] count',"always @(posedge clk) if(rst) count<=0; else if(en) count<=count+1'b1;",[('step2',("count+1'b1","count+2'd2")),('no_hold',('else if(en)','else'))],'reg clk=0,rst=0,en=0;wire [7:0] count;integer i,expected;counter dut(clk,rst,en,count);always #5 clk=~clk;task step;input r,e;begin @(negedge clk);rst=r;en=e;@(posedge clk);if(r)expected=0;else if(e)expected=(expected+1)%256;#1;if(count!==expected[7:0])$fatal(1,"count mismatch");end endtask',[('boundary','Increment and hold','expected=0;step(1,1);step(0,1);step(0,0);'),('wrap','Wrap and reset priority','expected=0;step(1,0);for(i=0;i<300;i=i+1)step(0,1);step(1,1);step(0,0);'),('seeded','Seeded enable/reset','expected=0;step(1,0);for(i=0;i<500;i=i+1)step(($random(seed)&31)==0,$random(seed)&1);')])
fbody="""reg [7:0] mem[0:1]; reg rd,wr; reg [1:0] n;
wire push=in_valid&&in_ready; wire pop=out_valid&&out_ready;
assign in_ready=(n<2); assign out_valid=(n!=0); assign out_data=mem[rd];
always @(posedge clk) if(rst) begin rd<=0;wr<=0;n<=0;end else begin
if(push) begin mem[wr]<=in_data;wr<=~wr;end
if(pop) rd<=~rd;
case({push,pop}) 2'b10:n<=n+1;2'b01:n<=n-1;default:n<=n;endcase end"""
stim='reg clk=0,rst=0,in_valid=0,out_ready=0;reg[7:0]in_data=0;wire in_ready,out_valid;wire[7:0]out_data;integer i,n=0,head=0,tail=0;reg[7:0]q[0:4095];reg push,pop;fifo dut(clk,rst,in_valid,in_data,in_ready,out_ready,out_valid,out_data);always #5 clk=~clk;task step;input r,v,ready;input[7:0]d;begin @(negedge clk);rst=r;in_valid=v;out_ready=ready;in_data=d;#1;if(!r)begin if(in_ready!==(n<2)||out_valid!==(n>0))$fatal(1,"fifo flags");if(n>0&&out_data!==q[head])$fatal(1,"fifo order");end push=v&&(n<2);pop=ready&&(n>0);@(posedge clk);if(r)begin n=0;head=0;tail=0;end else begin if(pop)head=head+1;if(push)begin q[tail]=d;tail=tail+1;end n=n+push-pop;end #1;end endtask'
add('fifo','repair','input clk,rst,in_valid, input [7:0] in_data, output in_ready, input out_ready, output out_valid, output [7:0] out_data',fbody,[('wrong_read',('mem[rd]','mem[wr]')),('bad_count',("default:n<=n;","default:n<=0;"))],stim,[('boundary','Fill stall simultaneous drain','step(1,0,0,0);step(0,1,0,10);step(0,0,0,0);step(0,1,0,20);step(0,1,1,30);step(0,1,1,40);step(0,0,1,0);step(0,0,1,0);'),('reset','Reset occupied FIFO','step(1,0,0,0);step(0,1,0,5);step(1,1,1,6);step(0,0,1,0);step(0,1,0,9);step(0,0,1,0);'),('seeded','Seeded FIFO scoreboard','step(1,0,0,0);for(i=0;i<500;i=i+1)step(($random(seed)&63)==0,$random(seed)&1,$random(seed)&1,$random(seed));step(0,0,1,0);step(0,0,1,0);step(0,0,0,0);')])
ports='input clk,rst,in_valid, input [7:0] in_data, output in_ready, input out_ready, output out_valid, output [7:0] out_data'
helper="module elastic_stage(input clk,rst,v,input[7:0]d,output ready,input take,output reg valid,output reg[7:0]data); assign ready=!valid||take; always @(posedge clk) if(rst)begin valid<=0;data<=0;end else if(ready)begin valid<=v;if(v)data<=d;end endmodule\n"
stim=stim.replace('fifo dut','stream_pipeline dut').replace('n<2','n==0||ready').replace('push=v&&(n==0||ready)','push=v&&((n==0)||ready)')
add('stream_pipeline','repository',ports,'elastic_stage u(clk,rst,in_valid,in_data,in_ready,out_ready,out_valid,out_data);',[('drop',('in_valid,in_data','1\'b0,in_data')),('corrupt',('in_valid,in_data','in_valid,8\'b0'))],stim,[('boundary','Stall stability and replacement','step(1,0,0,0);step(0,1,0,10);step(0,0,0,0);step(0,1,1,20);step(0,0,1,0);step(0,0,0,0);'),('reset','Reset occupied stage','step(1,0,0,0);step(0,1,0,5);step(1,0,0,0);step(0,0,1,0);'),('seeded','Seeded elastic scoreboard','step(1,0,0,0);for(i=0;i<500;i=i+1)step(($random(seed)&63)==0,$random(seed)&1,$random(seed)&1,$random(seed));step(0,0,1,0);step(0,0,0,0);')],helper)
add('round_robin','repository','input clk,rst,accept, input [1:0] req, output [1:0] grant',"reg pref; choose_grant u(req,pref,grant); always @(posedge clk) if(rst)pref<=0;else if(accept&&|grant)pref<=grant[0];",[('stuck',('pref<=grant[0]','pref<=0')),('advance_stall',('accept&&|grant','|grant'))],'reg clk=0,rst=0,accept=0;reg[1:0]req=0;wire[1:0]grant;integer i;reg pref=0;reg[1:0]exp;round_robin dut(clk,rst,accept,req,grant);always #5 clk=~clk;task step;input r,a;input[1:0]q;begin @(negedge clk);rst=r;accept=a;req=q;#1;case(q)0:exp=0;1:exp=1;2:exp=2;3:exp=pref?2:1;endcase if(!r&&grant!==exp)$fatal(1,"grant mismatch");@(posedge clk);if(r)pref=0;else if(a&&exp!=0)pref=exp[0];#1;end endtask',[('boundary','Fairness and held preference','step(1,0,0);step(0,1,3);step(0,0,3);step(0,0,3);step(0,1,3);step(0,1,3);'),('reset','Reset priority and no requests','step(1,0,0);step(0,1,1);step(1,1,3);step(0,1,3);step(0,1,0);step(0,1,2);'),('seeded','Seeded arbitration scoreboard','step(1,0,0);for(i=0;i<500;i=i+1)step(($random(seed)&63)==0,$random(seed)&1,$random(seed)&3);')],"module choose_grant(input[1:0]req,input pref,output[1:0]grant);assign grant=req==3?(pref?2'b10:2'b01):req;endmodule\n")
(R/'suite.json').write_text(json.dumps(dict(schema_version=1,id='rtl-core-v1',title='Portable RTL starter controls',origin='locally_authored',tasks=TASKS),indent=2)+'\n')
